
'use strict';
const $=id=>document.getElementById(id);
const moveHint=document.createElement('p');moveHint.id='moveHint';moveHint.style.cssText='font-size:12px;color:#e4eddd;min-height:20px';$('story').after(moveHint);
let mode='none',baseline=null,sample=null,playing=false,paused=false,index=0,success=false,startedAt=0,totalPaused=0,pauseAt=0,calibration=null,calibrationSamples=[],replay=false,simPulseUntil=0,lastSensorAt=0,lastOrientationAt=0,energy=0,motionAt=-Infinity,gravity=null,trial=null;
let recognizer=new MQ.Recognizer(),events=[],attempts=[],trace=[],sessionId=crypto.randomUUID?crypto.randomUUID():String(Date.now()),sim={roll:0,pitch:0},lastFrame=0,completedCount=0;
const SESSION_DATE=new Date().toISOString();
let visualProgress=0;
function log(type,extra={}){events.push({sessionId,at:new Date().toISOString(),elapsedMs:Math.round(performance.now()-startedAt),type,input:mode,condition:$('condition').value,participant:$('participant').value.trim(),...extra});}
function config(){return {tiltDegrees:$('difficulty').value==='gentle'?15:24};}
function setStatus(text){$('sensorStatus').textContent=text;}
function updateBadge(){const fresh=sample&&performance.now()-sample.at<MQ.SETTINGS.staleMs;$('modeBadge').textContent=mode==='simulation'?(replay?'SIMULATED WALKTHROUGH':'DESKTOP SIMULATION'):mode==='sensor'?(fresh?'LIVE PHONE SENSORS':'PHONE · WAITING FOR DATA'):'INPUT NOT CONNECTED';$('modeBadge').classList.toggle('synthetic',mode==='simulation');$('liveDot').classList.toggle('on',!!fresh);}
function stopGame(){playing=false;paused=false;success=false;replay=false;trial=null;recognizer.reset();$('game').classList.remove('riding','unstable','momentum');$('pauseBtn').hidden=true;$('nextBtn').hidden=true;$('startBtn').hidden=false;$('startBtn').textContent='Begin ride ↗';$('condition').disabled=false;$('difficulty').disabled=false;}
function switchMode(next){stopGame();mode=next;baseline=null;sample=null;gravity=null;energy=0;motionAt=-Infinity;lastOrientationAt=0;calibration=null;calibrationSamples=[];index=0;completedCount=0;$('simulation').hidden=next!=='simulation';$('calibrateBtn').disabled=false;$('startBtn').disabled=true;$('calibrationStatus').textContent='Not set';$('counter').textContent='0 / 6 encounters';$('moveName').textContent='Find your spark.';$('story').textContent='Calibrate your comfortable neutral position, then begin.';setProgress(0,false);log('input-selected');updateBadge();}
async function connectSensors(){
  if(!window.isSecureContext){setStatus('Motion input needs HTTPS. Local network HTTP is not sufficient. Use an HTTPS host; do not bypass certificate warnings.');return;}
  if(!('DeviceOrientationEvent'in window)||!('DeviceMotionEvent'in window)){setStatus('This browser does not expose phone motion sensors. Try a supported phone, or desktop simulation.');return;}
  try{
    const permissions=[];
    if(typeof DeviceOrientationEvent.requestPermission==='function')permissions.push(DeviceOrientationEvent.requestPermission());
    if(typeof DeviceMotionEvent.requestPermission==='function')permissions.push(DeviceMotionEvent.requestPermission());
    const grants=await Promise.all(permissions);
    if(grants.some(x=>x!=='granted')){setStatus('Motion access was not granted. You can retry yourself or use desktop simulation.');return;}
    switchMode('sensor');setStatus('Waiting for orientation and acceleration data. Keep the screen in portrait orientation.');
  }catch(e){setStatus('Could not connect motion input: '+e.message);}
}
window.addEventListener('deviceorientation',e=>{if(mode!=='sensor'||!Number.isFinite(e.beta)||!Number.isFinite(e.gamma))return;lastOrientationAt=performance.now();sample={beta:e.beta,gamma:e.gamma,at:lastOrientationAt,energy,motionAt};lastSensorAt=lastOrientationAt;});
window.addEventListener('devicemotion',e=>{if(mode!=='sensor')return;let a=e.acceleration;if(a&&[a.x,a.y,a.z].every(Number.isFinite)){energy=Math.hypot(a.x,a.y,a.z);}else{a=e.accelerationIncludingGravity;if(!a||![a.x,a.y,a.z].every(Number.isFinite))return;if(!gravity)gravity={x:a.x,y:a.y,z:a.z};for(const k of ['x','y','z'])gravity[k]=.88*gravity[k]+.12*a[k];energy=Math.hypot(a.x-gravity.x,a.y-gravity.y,a.z-gravity.z);}motionAt=performance.now();if(sample)sample={...sample,energy,motionAt};});
function calibrate(){if(playing||trial){setStatus('Pause and restart before recalibrating.');return;}baseline=null;calibration=performance.now();calibrationSamples=[];$('calibrationStatus').textContent='Hold still for 2 seconds';$('calibrateBtn').disabled=true;log('calibration-start');}
function setProgress(p,done){visualProgress=p;const visible=$('condition').value==='binary'&&!done?0:p;$('progressRing').style.strokeDashoffset=452.389*(1-visible);$('orb').classList.toggle('success',done);$('game').classList.toggle('success-flash',done);$('confidence').textContent=done?'Movement recognized ✓':$('condition').value==='binary'?'Success-only feedback':`Completion progress · ${Math.round(p*100)}%`;}
function nextSequence(){const q=MQ.SEQUENCES[index],g=MQ.GESTURES[q.gesture];$('game').className='game riding '+(index>=4?'sanctuary':index>=2?'canyon':'');$('chapter').textContent=`CHAPTER 0${Math.floor(index/2)+1} / ${q.place.toUpperCase()}`;$('location').textContent=`ENCOUNTER ${index+1} OF ${MQ.SEQUENCES.length}`;$('moveName').textContent=g.name;$('story').textContent=q.story;$('gestureIcon').textContent=g.icon;$('feedback').textContent=g.hint;$('nextBtn').hidden=true;$('pauseBtn').hidden=false;$('pauseBtn').textContent='Pause';$('startBtn').hidden=true;success=false;recognizer=new MQ.Recognizer(config());setProgress(0,false);document.querySelectorAll('.journey span').forEach((el,i)=>el.classList.toggle('active',i<=Math.floor(index/2)));log('encounter-start',{gesture:q.gesture,encounter:index+1});}
function start(){if(!baseline||mode==='none'){setStatus('Connect input and calibrate first.');return;}index=0;completedCount=0;playing=true;paused=false;startedAt=performance.now();totalPaused=0;$('condition').disabled=true;$('difficulty').disabled=true;$('calibrateBtn').disabled=true;log('adventure-start');nextSequence();}
function next(){if(!playing||!success)return;index++;if(index>=MQ.SEQUENCES.length){playing=false;replay=false;$('game').classList.remove('riding');$('game').classList.add('completed');$('moveName').textContent='You brought back the light.';$('story').textContent='Six small movements. One complete adventure. Export your session or start another journey.';$('location').textContent='JOURNEY COMPLETE';$('feedback').textContent=mode==='simulation'?'Desktop simulation complete; physical-device validation still pending.':'Adventure complete — recognition is not a fitness assessment.';$('nextBtn').hidden=true;$('pauseBtn').hidden=true;$('startBtn').hidden=false;$('startBtn').textContent='Play again ↗';$('condition').disabled=false;$('difficulty').disabled=false;$('calibrateBtn').disabled=false;log('adventure-complete');return;}nextSequence();}
function togglePause(){if(!playing||success)return;paused=!paused;if(paused){pauseAt=performance.now();recognizer.reset();$('pauseBtn').textContent='Resume';$('feedback').textContent='Paused. Rest and resume when ready.';setProgress(0,false);}else{totalPaused+=performance.now()-pauseAt;$('pauseBtn').textContent='Pause';}log(paused?'paused':'resumed');}
function pulse(){simPulseUntil=performance.now()+100;}
function setSim(r,p){sim.roll=r;sim.pitch=p;$('simRoll').value=r;$('simPitch').value=p;}
function runReplay(){if(mode!=='simulation')switchMode('simulation');replay=true;setSim(0,0);baseline={beta:0,gamma:0};$('calibrationStatus').textContent='Simulation baseline';$('startBtn').disabled=false;start();log('synthetic-walkthrough-start');}
function exportData(kind){log('export',{format:kind});const meta={project:'MotionQuest',version:'0.1.0',sessionId,createdAt:SESSION_DATE,participant:$('participant').value.trim(),input:mode,synthetic:mode==='simulation',condition:$('condition').value,settings:{...MQ.SETTINGS,...config()},calibration:baseline,notice:'Rule-based progress is not calibrated confidence. Adventure completion is not independently labeled recognition accuracy.',events,recognitionTrials:attempts};const rows=events.map(e=>({sessionId:e.sessionId,at:e.at,type:e.type,input:e.input,synthetic:e.input==='simulation',condition:e.condition,participant:e.participant,gesture:e.gesture??'',encounter:e.encounter??'',progress:e.progress??'',actual:e.actual??'',detected:e.detected??'',durationMs:e.durationMs??'',latencyMs:e.latencyMs??''}));const blob=new Blob([kind==='json'?JSON.stringify(meta,null,2):MQ.csv(rows)],{type:kind==='json'?'application/json':'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`MotionQuest-${sessionId.slice(0,8)}.${kind}`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);$('exportStatus').textContent='Downloaded '+a.download+'. Files contain only this tab’s session; no uploads occur.';}
function startTrial(){if(!baseline||playing){$('trialStatus').textContent='Connect and calibrate input, then restart to leave the adventure before testing.';return;}trial={start:performance.now(),actual:$('groundTruth').value,input:mode,condition:$('condition').value,recognizers:Object.fromEntries(Object.keys(MQ.GESTURES).map(k=>[k,new MQ.Recognizer(config())])),detected:'none',latencyMs:null};$('trialBtn').disabled=true;$('groundTruth').disabled=true;log('recognition-trial-start',{actual:trial.actual});}
let replayStepAt=0;
function updateVisualFeedback(fresh){const game=$('game'),cue=$('inputCue');let roll=0,pitch=0,motion=0;if(fresh&&baseline){roll=MQ.angleDiff(sample.gamma,baseline.gamma);pitch=MQ.angleDiff(sample.beta,baseline.beta);motion=Number.isFinite(sample.energy)?sample.energy:0;}const steer=Math.max(-1,Math.min(1,roll/35));const forward=Math.max(0,Math.min(1,-pitch/35));game.style.setProperty('--horse-shift',`${steer*46}px`);game.style.setProperty('--world-shift',`${steer*-18}px`);game.style.setProperty('--horse-lean',`${steer*5}deg`);const jumping=playing&&!paused&&MQ.SEQUENCES[index]?.gesture==='jump';game.style.setProperty('--horse-lift',`${jumping?-Math.sin(visualProgress*Math.PI)*72:0}px`);game.classList.toggle('momentum',motion>2.4);game.classList.toggle('unstable',playing&&!paused&&MQ.SEQUENCES[index]?.gesture==='steady'&&visualProgress<.85);cue.classList.toggle('visible',playing&&!paused&&fresh);if(!playing||paused)cue.textContent='';else if(!fresh)cue.textContent='Waiting for movement';else if(Math.abs(steer)>.2)cue.textContent=steer<0?'Steering left':'Steering right';else if(forward>.2)cue.textContent='Preparing to jump';else if(motion>2.4)cue.textContent='Momentum pulse';else cue.textContent=MQ.SEQUENCES[index]?.gesture==='steady'?'Ground settling':'Centered';}
function loop(now){requestAnimationFrame(loop);if(now-lastFrame<32)return;lastFrame=now;
  if(mode==='simulation'){sample={beta:sim.pitch,gamma:sim.roll,at:now,energy:now<simPulseUntil?3.4:0,motionAt:now};}
  updateBadge();
  if(calibration!==null){if(sample&&now-sample.at<200&&!calibrationSamples.some(s=>s.at===sample.at))calibrationSamples.push({...sample});if(now-calibration>=2000){try{if(calibrationSamples.length<15)throw Error('No fresh sensor stream. Check access on a phone.');const b=MQ.calibrate(calibrationSamples);const spread=Math.max(...calibrationSamples.map(s=>Math.hypot(MQ.angleDiff(s.beta,b.beta),MQ.angleDiff(s.gamma,b.gamma))));if(spread>8)throw Error('Too much movement. Hold comfortably still and retry.');baseline=b;$('calibrationStatus').textContent='Ready ✓';$('startBtn').disabled=false;setStatus(mode==='simulation'?'Synthetic input connected. This does not validate phone sensors.':'Neutral position saved. Start your adventure.');log('calibration-success',{samples:calibrationSamples.length});}catch(e){baseline=null;$('calibrationStatus').textContent='Retry calibration';setStatus(e.message);}calibration=null;$('calibrateBtn').disabled=false;}}
  const fresh=sample&&now-sample.at<=MQ.SETTINGS.staleMs;
  if(fresh){$('roll').textContent=Math.round(baseline?MQ.angleDiff(sample.gamma,baseline.gamma):sample.gamma)+'°';$('pitch').textContent=Math.round(baseline?MQ.angleDiff(sample.beta,baseline.beta):sample.beta)+'°';$('energy').textContent=Number.isFinite(sample.energy)?sample.energy.toFixed(1):'—';trace.push(baseline?MQ.angleDiff(sample.gamma,baseline.gamma):sample.gamma);if(trace.length>100)trace.shift();}else{$('roll').textContent='—';$('pitch').textContent='—';$('energy').textContent='—';}
  drawSignal(fresh);updateVisualFeedback(fresh);
  if(playing&&!paused&&!success){const q=MQ.SEQUENCES[index];if(replay){if(q.gesture==='left')setSim(-30,0);else if(q.gesture==='right')setSim(30,0);else if(q.gesture==='jump')setSim(0,-30);else if(q.gesture==='steady')setSim(0,0);else{setSim(0,0);if(now-replayStepAt>650){pulse();replayStepAt=now;}}}const result=recognizer.readMotion(sample,q.gesture,baseline,now);setProgress(result.progress,false);$('feedback').textContent=result.reason;if(result.success){success=true;completedCount++;$('counter').textContent=`${completedCount} / 6 encounters`;$('feedback').textContent=q.reward+' ✓';$('gestureIcon').textContent='✓';setProgress(1,true);$('nextBtn').hidden=false;$('pauseBtn').hidden=true;log('gesture-recognized',{gesture:q.gesture,encounter:index+1,progress:1});if($('haptics').checked&&navigator.vibrate)navigator.vibrate([60,40,60]);if(replay)setTimeout(()=>{if(replay&&playing&&success)next();},1500);}}
  if(playing){const elapsed=((paused?pauseAt:now)-startedAt-totalPaused)/1000;$('sessionTime').textContent=String(Math.floor(elapsed/60)).padStart(2,'0')+':'+String(Math.floor(elapsed%60)).padStart(2,'0');}
  if(trial){for(const [k,r]of Object.entries(trial.recognizers)){const x=r.readMotion(sample,k,baseline,now);if(x.success&&trial.detected==='none'){trial.detected=k;trial.latencyMs=Math.round(now-trial.start);}}$('trialStatus').textContent=`Recording ${Math.max(0,5-(now-trial.start)/1000).toFixed(1)}s · detected: ${trial.detected}`;if(now-trial.start>=5000){const row={actual:trial.actual,detected:trial.detected,input:trial.input,synthetic:trial.input==='simulation',condition:trial.condition,durationMs:Math.round(now-trial.start),latencyMs:trial.latencyMs};attempts.push(row);log('recognition-trial',row);$('trialStatus').textContent=`Trial saved. Actual: ${row.actual}; detected: ${row.detected}. ${attempts.length} trials in this session.`;trial=null;$('trialBtn').disabled=false;$('groundTruth').disabled=false;}}
}
function drawSignal(fresh){const c=$('signal'),ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);ctx.strokeStyle='#324950';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,h/2);ctx.lineTo(w,h/2);ctx.stroke();if(!fresh)return;ctx.strokeStyle=mode==='simulation'?'#dfbc84':'#b8d69e';ctx.lineWidth=2;ctx.beginPath();trace.forEach((v,i)=>{const x=i*w/99,y=h/2-v*.75;i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.stroke();}
const desktopControls=[...document.querySelectorAll('[data-control]')];
function pressControl(control){if(mode!=='simulation')return;if(control==='left')setSim(-30,0);if(control==='right')setSim(30,0);if(control==='jump')setSim(0,-30);if(control==='steady')setSim(0,0);if(control==='momentum')pulse();desktopControls.forEach(button=>button.classList.toggle('active',button.dataset.control===control));}
function releaseControl(control){if(['left','right','jump'].includes(control))setSim(0,0);desktopControls.forEach(button=>button.classList.remove('active'));}
desktopControls.forEach(button=>{button.addEventListener('pointerdown',event=>{event.preventDefault();pressControl(button.dataset.control);});button.addEventListener('pointerup',()=>releaseControl(button.dataset.control));button.addEventListener('pointercancel',()=>releaseControl(button.dataset.control));button.addEventListener('pointerleave',()=>releaseControl(button.dataset.control));});
const motionModel=new MotionQuestModel.MotionModel();
function currentFeatures(){return MotionQuestModel.featureVector(sample,baseline,MQ.angleDiff);}
function modelCounts(){const counts=motionModel.counts();return Object.entries(counts).map(([label,count])=>`${label}: ${count}`).join(' · ')||'no examples';}
$('knnAdd').onclick=()=>{const label=$('groundTruth').value;if(!MotionQuestModel.available()){$('knnStatus').textContent='KNN library did not load. Check the internet connection and refresh.';return;}if(!baseline||!currentFeatures()){$('knnStatus').textContent='Choose an input and calibrate before adding an example.';return;}motionModel.add(label,currentFeatures());$('knnStatus').textContent=`Example added · ${modelCounts()}`;};
$('knnPredict').onclick=async()=>{if(!MotionQuestModel.available()){$('knnStatus').textContent='KNN library did not load. Check the internet connection and refresh.';return;}const result=await motionModel.predict(currentFeatures());$('knnStatus').textContent=result?`KNN predicts ${result.label} · ${Math.round((result.confidences[result.label]||0)*100)}% neighbor agreement · ${modelCounts()}`:'Add examples for at least two movement labels before predicting.';};
$('knnReset').onclick=()=>{motionModel.clear();$('knnStatus').textContent='KNN examples cleared.';};
$('sensorBtn').onclick=connectSensors;$('simBtn').onclick=()=>{switchMode('simulation');setStatus('Desktop controls selected. Calibrate, then use the movement pad.');};$('calibrateBtn').onclick=calibrate;$('startBtn').onclick=start;$('pauseBtn').onclick=togglePause;$('nextBtn').onclick=next;$('resetBtn').onclick=()=>{stopGame();index=0;completedCount=0;$('counter').textContent='0 / 6 encounters';$('calibrateBtn').disabled=mode==='none';$('startBtn').disabled=!baseline;$('moveName').textContent='Ready for another journey?';$('story').textContent='Keep your calibration, or recalibrate before starting.';setProgress(0,false);log('restart');};$('simRoll').oninput=e=>sim.roll=Number(e.target.value);$('simPitch').oninput=e=>sim.pitch=Number(e.target.value);$('neutralBtn').onclick=()=>setSim(0,0);$('pulseBtn').onclick=pulse;$('replayBtn').onclick=runReplay;$('exportBtn').onclick=()=>exportData('csv');$('jsonBtn').onclick=()=>exportData('json');$('trialBtn').onclick=startTrial;$('studyBtn').onclick=()=>{$('testBench').hidden=!$('testBench').hidden;};$('helpBtn').onclick=()=>$('help').showModal();$('closeHelp').onclick=()=>$('help').close();$('skipBtn').onclick=()=>{if(playing){log('encounter-skipped',{encounter:index+1,gesture:MQ.SEQUENCES[index].gesture});success=true;next();}$('help').close();};
window.addEventListener('keydown',e=>{if(mode!=='simulation'||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;if(['ArrowLeft','ArrowRight','ArrowUp',' '].includes(e.key))e.preventDefault();if(e.key==='ArrowLeft')pressControl('left');if(e.key==='ArrowRight')pressControl('right');if(e.key==='ArrowUp')pressControl('jump');if(e.key===' '&&!e.repeat)pressControl('momentum');});
window.addEventListener('keyup',e=>{if(mode!=='simulation')return;if(e.key==='ArrowLeft')releaseControl('left');if(e.key==='ArrowRight')releaseControl('right');if(e.key==='ArrowUp')releaseControl('jump');if(e.key===' ')releaseControl('momentum');});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&playing&&!paused&&!success)togglePause();});
window.addEventListener('orientationchange',()=>{if(mode==='sensor'){stopGame();baseline=null;$('startBtn').disabled=true;$('calibrateBtn').disabled=false;$('calibrationStatus').textContent='Rotate back to portrait and recalibrate';log('screen-rotation');}});

const originalShowEncounter=nextSequence;
nextSequence=function(){originalShowEncounter();moveHint.textContent=MQ.GESTURES[MQ.SEQUENCES[index].gesture].hint;};
const originalStart=start;
start=function(){originalStart();$('counter').textContent=`${completedCount} / 6 encounters`;};
$('startBtn').onclick=start;
requestAnimationFrame(loop);
